// ABOUTME: Hello-world for the monty-backed code-adapter — runs Python that hits real SEC EDGAR.
// ABOUTME: Proof-of-concept that the agent can write its own structured-API adapters.

import { MontyRuntime } from "../src/code-adapter.js";

// Pretend this Python was generated by the agent in response to "find SEC filings".
// Notes for future agent-written adapters:
//  - No `await` keyword. External fns returning Promises are auto-awaited by the host.
//  - Stdlib only: json, re, datetime, asyncio, typing, sys, os (no requests, no httpx).
//  - Host functions available: http_get, http_post, now, log.
const EDGAR_PY = `
import json

params = "q=" + query
if forms:
    params = params + "&forms=" + ",".join(forms)

resp = http_get(
    "https://efts.sec.gov/LATEST/search-index?" + params,
    {"Accept": "application/json"},
)

results = []
if resp["status"] == 200:
    data = json.loads(resp["body_text"])
    hits = data.get("hits", {}).get("hits", [])
    for hit in hits:
        src = hit.get("_source", {})
        ciks = src.get("ciks") or []
        cik = ciks[0] if ciks else None
        accession = src.get("adsh") or hit.get("_id")
        if not cik or not accession:
            continue
        padded = cik.lstrip("0").zfill(10)
        no_dashes = accession.replace("-", "")
        url = (
            "https://www.sec.gov/Archives/edgar/data/"
            + str(int(padded)) + "/" + no_dashes + "/"
            + accession + "-index.htm"
        )
        names = src.get("display_names") or ["Unknown"]
        company = names[0]
        form = src.get("file_type") or "filing"
        filed = src.get("file_date", "")
        title = company + " - " + form
        if filed:
            title = title + " (filed " + filed + ")"
        snippet_str = "EDGAR filing: " + form
        if filed:
            snippet_str = snippet_str + ", " + filed
        snippet_str = snippet_str + " - " + company
        results.append({"title": title, "url": url, "snippet": snippet_str})

results
`;

type SearchResult = { title: string; url: string; snippet: string };

async function main() {
  const runtime = new MontyRuntime();
  const query = "Tesla annual report";
  const forms = ["10-K"];

  console.log(`\nQuerying EDGAR for "${query}" (forms=${forms.join(",")})...\n`);
  const t0 = performance.now();
  const results = await runtime.run<
    { query: string; forms: string[] },
    SearchResult[]
  >(EDGAR_PY, { query, forms });
  const elapsed = Math.round(performance.now() - t0);

  console.log(`Got ${results.length} results in ${elapsed}ms:\n`);
  for (const [i, r] of results.slice(0, 5).entries()) {
    console.log(`${i + 1}. ${r.title}`);
    console.log(`   ${r.url}`);
    console.log(`   ${r.snippet}\n`);
  }
}

main().catch((err) => {
  console.error("hello-monty failed:", err);
  process.exit(1);
});
